/bin/bash -lc "python -c 'import os,urllib.parse,requests,json; tid=\"toolshed.g2.bx.psu.edu/repos/iuc/minimap2/minimap2/2.31+galaxy1\"; u=os.environ[\"GALAXY_URL\"]+\"/api/tools/\"+urllib.parse.quote(tid,safe=\"\"); k=open(os.environ[\"GALAXY_API_KEY_FILE\"]).read().strip(); x=requests.get(u,headers={\"x-api-key\":k},params={\"io_details\":\"true\"},timeout=30).json();

def walk(x):
  if isinstance(x,dict):
    if x.get(\"name\")==\"ref_file\" and \"options\" in x:
      for o in x[\"options\"]:
        if any(t in o[0].lower() for t in (\"homo sapiens\",\"mus musculus\",\"sus scrofa\",\"human\",\"mouse\",\"pig\")): print(o)
    for v in x.values(): walk(v)
  elif isinstance(x,list):
    for v in x: walk(v)
walk(x)'"

